static UILabel *TFControlLabel(NSString *text,UIFontTextStyle style){UILabel *l=[UILabel new];l.text=text;l.font=[UIFont preferredFontForTextStyle:style];l.numberOfLines=0;return l;}
static UIView *TFControlLine(void){UIView *v=[UIView new];v.backgroundColor=UIColor.separatorColor;[v.heightAnchor constraintEqualToConstant:.5].active=YES;return v;}
static UIButton *TFControlButton(NSString *title,NSString *symbol,void(^action)(void)){UIButton *b=[UIButton buttonWithType:UIButtonTypeSystem];UIButtonConfiguration *c=[UIButtonConfiguration plainButtonConfiguration];c.title=title;c.image=[UIImage systemImageNamed:symbol];c.imagePadding=10;c.contentInsets=NSDirectionalEdgeInsetsMake(8,10,8,10);c.baseForegroundColor=UIColor.labelColor;c.titleLineBreakMode=NSLineBreakByTruncatingMiddle;c.titleTextAttributesTransformer=^NSDictionary *(NSDictionary *attrs){NSMutableDictionary *a=[attrs mutableCopy];a[NSFontAttributeName]=[UIFont systemFontOfSize:14 weight:UIFontWeightMedium];return a;};b.configuration=c;b.contentHorizontalAlignment=UIControlContentHorizontalAlignmentLeading;b.layer.cornerRadius=12;[b.heightAnchor constraintGreaterThanOrEqualToConstant:44].active=YES;[b addAction:[UIAction actionWithHandler:^(UIAction *unused){if(action)action();}] forControlEvents:UIControlEventTouchUpInside];return b;}
@interface TFAIFloatingControls : UIViewController <UIPopoverPresentationControllerDelegate>
@property UIStackView *stack;
@end
@implementation TFAIFloatingControls
- (instancetype)init{if((self=[super init])){self.modalPresentationStyle=UIModalPresentationPopover;self.popoverPresentationController.delegate=self;}return self;}
- (void)viewDidLoad{[super viewDidLoad];self.view.backgroundColor=UIColor.secondarySystemGroupedBackgroundColor;self.view.layer.cornerRadius=22;UIScrollView *scroll=[UIScrollView new];scroll.translatesAutoresizingMaskIntoConstraints=NO;[self.view addSubview:scroll];self.stack=[UIStackView new];self.stack.axis=UILayoutConstraintAxisVertical;self.stack.spacing=9;self.stack.translatesAutoresizingMaskIntoConstraints=NO;[scroll addSubview:self.stack];[NSLayoutConstraint activateConstraints:@[[scroll.leadingAnchor constraintEqualToAnchor:self.view.leadingAnchor],[scroll.trailingAnchor constraintEqualToAnchor:self.view.trailingAnchor],[scroll.topAnchor constraintEqualToAnchor:self.view.topAnchor],[scroll.bottomAnchor constraintEqualToAnchor:self.view.bottomAnchor],[self.stack.topAnchor constraintEqualToAnchor:scroll.contentLayoutGuide.topAnchor constant:12],[self.stack.bottomAnchor constraintEqualToAnchor:scroll.contentLayoutGuide.bottomAnchor constant:-12],[self.stack.leadingAnchor constraintEqualToAnchor:scroll.contentLayoutGuide.leadingAnchor constant:12],[self.stack.trailingAnchor constraintEqualToAnchor:scroll.contentLayoutGuide.trailingAnchor constant:-12],[self.stack.widthAnchor constraintEqualToAnchor:scroll.frameLayoutGuide.widthAnchor constant:-24]]];}
- (void)viewDidLayoutSubviews{[super viewDidLayoutSubviews];CGFloat width=MIN(350,MAX(260,self.view.bounds.size.width));CGSize fit=[self.stack systemLayoutSizeFittingSize:CGSizeMake(width-24,0) withHorizontalFittingPriority:UILayoutPriorityRequired verticalFittingPriority:UILayoutPriorityFittingSizeLevel];CGFloat maxHeight=MIN(570,MAX(260,self.view.window.bounds.size.height*.68));CGSize size=CGSizeMake(width,MIN(maxHeight,fit.height+24));if(fabs(self.preferredContentSize.height-size.height)>1)self.preferredContentSize=size;}
- (UIModalPresentationStyle)adaptivePresentationStyleForPresentationController:(UIPresentationController *)controller{return UIModalPresentationNone;}
- (UIModalPresentationStyle)adaptivePresentationStyleForPresentationController:(UIPresentationController *)controller traitCollection:(UITraitCollection *)traits{return UIModalPresentationNone;}
@end
