elector(sliderChanged:) forControlEvents:UIControlEventValueChanged];self.slider.hidden=self.options.count<2;[self.stack addArrangedSubview:self.slider];self.labels=[UIStackView new];self.labels.axis=UILayoutConstraintAxisHorizontal;self.labels.distribution=UIStackViewDistributionEqualSpacing;self.labels.spacing=3;self.labels.hidden=self.options.count<2;for(NSDictionary *option in self.options){UILabel *label=TFControlLabel(option[@"name"],UIFontTextStyleCaption2);label.textColor=UIColor.secondaryLabelColor;[self.labels addArrangedSubview:label];}[self.stack addArrangedSubview:self.labels];UILabel *origin=TFControlLabel(TFAIThinkingConfiguration(self.connection?:@{})[@"source"],UIFontTextStyleCaption2);origin.textColor=UIColor.tertiaryLabelColor;[self.stack addArrangedSubview:origin];NSUInteger index=[self.options indexOfObjectPassingTest:^BOOL(NSDictionary *o,NSUInteger i,BOOL *stop){return [o[@"id"] isEqual:weak.effort];}];[self renderIndex:index==NSNotFound?0:index];self.preferredContentSize=CGSizeMake(330,self.options.count>1?235:180);}
