- (void)viewDidLoad{[super viewDidLoad];UILabel *caption=TFControlLabel(@"AI 可以执行哪些操作？",UIFontTextStyleCaption1);caption.textColor=UIColor.secondaryLabelColor;[self.stack addArrangedSubview:caption];__weak typeof(self) weak=self;NSArray *items=@[@[@"ask",@"逐次批准",@"读取无需批准；构建和修改前分别确认",@"hand.raised"],@[@"build",@"允许本会话构建",@"自动构建；文件修改仍预览并批准",@"hammer"],@[@"full",@"项目完全访问",@"自动读写当前项目和构建，保留修改记录",@"exclamationmark.shield"]];for(NSArray *item in items){UIButton *b=TFControlButton(item[1],item[3],^{if(weak.changePermission)weak.changePermission(item[0],weak.allowPush,weak.allowDownload);});UIButtonConfiguration *c=b.configuration;c.subtitle=item[2];c.subtitleTextAttributesTransformer=^NSDictionary *(NSDictionary *attrs){NSMutableDictionary *a=[attrs mutableCopy];a[NSFontAttributeName]=[UIFont preferredFontForTextStyle:UIFontTextStyleCaption2];a[NSForegroundColorAttributeName]=UIColor.secondaryLabelColor;return a;};c.titleAlignment=UIButtonConfigurationTitleAlignmentLeading;c.titlePadding=4;c.contentInsets=NSDirectionalEdgeInsetsMake(9,8,9,8);if([item[0] isEqual:self.mode]){c.baseForegroundColor=[self.mode isEqual:@"ask"]?UIColor.labelColor:UIColor.systemOrangeColor;c.background.backgroundColor=UIColor.tertiarySystemFillColor;b.accessibilityValue=@"已选择";}b.configuration=c;[self.stack addArrangedSubview:b];}[self.stack addArrangedSubview:TFControlLine()];UILabel *scope=TFControlLabel([NSString stringWithFormat:@"当前范围：%@ / 当前会话\n设置随会话保存，停止任务不清除选择。参考附件保持只读。",self.projectName?:@"当前项目"],UIFontTextStyleCaption2);scope.textColor=UIColor.secondaryLabelColor;[self.stack addArrangedSubview:scope];UIButton *more=TFControlButton(@"上传与下载设置",@"chevron.down",^{weak.extraStack.hidden=!weak.extraStack.hidden;[weak.view setNeedsLayout];});[self.stack addArrangedSubview:more];self.extraStack=[UIStackView new];self.extraStack.axis=UILayoutConstraintAxisVertical;self.extraStack.spacing=7;self.extraStack.hidden=YES;[self.stack addArrangedSubview:self.extraStack];self.pushSwitch=[UISwitch new];self.downloadSwitch=[UISwitch new];self.pushSwitch.on=self.allowPush;self.downloadSwitch.on=self.allowDownload;self.pushSwitch.enabled=self.downloadSwitch.enabled=[self.mode isEqual:@"full"];[self.pushSwitch addTarget:self action:@selector(networkChanged:) forControlEvents:UIControlEventValueChanged];[self.downloadSwitch addTarget:self action:@selector(networkChanged:) forControlEvents:UIControlEventValueChanged];NSArray *specs=@[@[@"自动推送当前项目到 Git 远端",self.pushSwitch],@[@"允许工具下载外部依赖",self.downloadSwitch]];for(NSArray *spec in specs){UIStackView *row=[UIStackView new];row.axis=UILayoutConstraintAxisHorizontal;row.alignment=UIStackViewAlignmentCenter;row.spacing=10;UILabel *text=TFControlLabel(spec[0],UIFontTextStyleCaption1);[row addArrangedSubview:text];[row addArrangedSubview:spec[1]];[self.extraStack addArrangedSubview:row];}UILabel *note=TFControlLabel(@"首次确认远端与分支，随后相同目标自动上传。关闭时仍逐次确认；模型对话继续使用已配置服务。",UIFontTextStyleCaption2);note.textColor=UIColor.secondaryLabelColor;[self.extraStack addArrangedSubview:note];self.preferredContentSize=CGSizeMake(350,350);}
