@end
UIViewController *TFAIModelControlsController(NSDictionary *connection,NSString *effort,void(^chooseModel)(void),void(^changeEffort)(NSString *)){TFAIModelControls *v=[TFAIModelControls new];v.connection=connection;v.effort=effort;v.chooseModel=chooseModel;v.changeEffort=changeEffort;return v;}
UIViewController *TFAIPermissionControlsController(NSString *mode,BOOL push,BOOL download,NSString *projectName,void(^changePermission)(NSString *,BOOL,BOOL)){TFAIPermissionControls *v=[TFAIPermissionControls new];v.mode=mode;v.allowPush=push;v.allowDownload=download;v.projectName=projectName;v.changePermission=changePermission;return v;}
